INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(524842, 52539, 772, '<td valign="top">This is a beautiful shot.. wish the horizon was level.. that woud make a great improvement :)<br/></td>', 'This is a beautiful shot.. wish the horizon was level.. that woud make a great improvement :)', '2003-12-29 00:12:25.000000', NULL, 1),
(524845, 52478, 1717, '<td valign="top">wow!  amazing shot!  great composition and exposure.  definitely a winner.</td>', 'wow!  amazing shot!  great composition and exposure.  definitely a winner.', '2003-12-29 00:14:12.000000', NULL, 1),
(524851, 52510, 327, '<td valign="top">Not too sure I understand you idea here as it relates to the challenge. &gt;?&lt;</td>', 'Not too sure I understand you idea here as it relates to the challenge. >?<', '2003-12-29 00:23:02.000000', NULL, 1),
(524852, 52444, 10170, '<td valign="top">Beautiful photo, and hard hitting message.  Love it.</td>', 'Beautiful photo, and hard hitting message.  Love it.', '2003-12-29 00:25:03.000000', NULL, 1),
(524855, 52537, 10170, '<td valign="top">Excellent.  Looks like a movie poster or something.  Very well done indeed.</td>', 'Excellent.  Looks like a movie poster or something.  Very well done indeed.', '2003-12-29 00:28:46.000000', NULL, 1),
(524856, 51884, 12896, '<td valign="top">nice..</td>', 'nice..', '2003-12-29 00:29:25.000000', NULL, 1),
(524857, 52536, 10170, '<td valign="top">Beautiful shot.  The stunning red hair works well with the black.</td>', 'Beautiful shot.  The stunning red hair works well with the black.', '2003-12-29 00:31:00.000000', NULL, 1),
(524859, 52542, 10170, '<td valign="top">Absolutely stunning.  Usually I would hate a border like this, but for this photo it really works well.</td>', 'Absolutely stunning.  Usually I would hate a border like this, but for this photo it really works well.', '2003-12-29 00:32:11.000000', NULL, 1),
(524860, 51919, 1031, '<td valign="top">I glad to se some people using "non-pretty" pictures; this is appropriately "gritty" for your topic. For some reason the inner, light border by the brick bothers me a little, maybe because it almost but doesn''t quite mimic the mortar lines. I''d like to see this with the inner black border touching the bricks.<br/>Also, you have a typo or syntax error -- the next-to--last word should be "than" (but I don''t deduct for typos!).</td>', 'I glad to se some people using "non-pretty" pictures; this is appropriately "gritty" for your topic. For some reason the inner, light border by the brick bothers me a little, maybe because it almost but doesn''t quite mimic the mortar lines. I''d like to see this with the inner black border touching the bricks.Also, you have a typo or syntax error -- the next-to--last word should be "than" (but I don''t deduct for typos!).', '2003-12-29 00:32:17.000000', NULL, 1),
(524861, 52519, 9232, '<td valign="top">Coule have used the tagline in the poster as subtext.  I like the angle you chose.</td>', 'Coule have used the tagline in the poster as subtext.  I like the angle you chose.', '2003-12-29 00:32:22.000000', NULL, 1),
(524862, 52539, 10170, '<td valign="top">Beautiful photo and really good choice the way you''ve done the text and border.</td>', 'Beautiful photo and really good choice the way you''ve done the text and border.', '2003-12-29 00:33:03.000000', NULL, 1),
(524863, 52550, 9232, '<td valign="top">A border and some text could have brought this together to explain the focus and motivation but this is a lovely photo.</td>', 'A border and some text could have brought this together to explain the focus and motivation but this is a lovely photo.', '2003-12-29 00:34:09.000000', NULL, 1),
(524864, 52534, 9232, '<td valign="top">Focus is a little soft.</td>', 'Focus is a little soft.', '2003-12-29 00:34:45.000000', NULL, 1),
(524865, 52542, 1031, '<td valign="top">A beautiful image and presentation. I think more black at the bottom and moving the type down would make it a more traditionally poster-shaped.</td>', 'A beautiful image and presentation. I think more black at the bottom and moving the type down would make it a more traditionally poster-shaped.', '2003-12-29 00:35:21.000000', NULL, 1),
(524866, 52405, 9232, '<td valign="top">I don''t like the text in a different colored area but I can see the usage of color from within the photo so it creates a link.</td>', 'I don''t like the text in a different colored area but I can see the usage of color from within the photo so it creates a link.', '2003-12-29 00:35:38.000000', NULL, 1),
(524867, 51848, 9232, '<td valign="top">Just a little blown out in a couple of places on the dominoes.</td>', 'Just a little blown out in a couple of places on the dominoes.', '2003-12-29 00:38:10.000000', NULL, 1),
(524868, 52275, 1031, '<td valign="top">Perspective distortion (?) on the right bothers me some. I might have tried cropping a square out of this, and put it on a vertical layout with two lines of type below, maybe shortening it to<br/>Walk Slowly,<br/>But Never Backwards</td>', 'Perspective distortion (?) on the right bothers me some. I might have tried cropping a square out of this, and put it on a vertical layout with two lines of type below, maybe shortening it toWalk Slowly,But Never Backwards', '2003-12-29 00:38:20.000000', NULL, 1),
(524869, 52510, 1031, '<td valign="top">Maybe this will motivate me to work on this technique -- I have a couple of good flying bird shots in the last month.</td>', 'Maybe this will motivate me to work on this technique -- I have a couple of good flying bird shots in the last month.', '2003-12-29 00:39:48.000000', NULL, 1),
(524871, 52507, 9232, '<td valign="top">Seems like there is a line across the photo up towards the top; it runs through the word "Teamwork"</td>', 'Seems like there is a line across the photo up towards the top; it runs through the word "Teamwork"', '2003-12-29 00:44:04.000000', NULL, 1),
(524873, 52557, 1031, '<td valign="top">Good use of a familiar symbol; good lighting, exposure, and color scheme. It''s a little odd having the quotation on the monument readable, since it''s different from your caption. In this one case, I might have considered blurring the type on the monument slightly.</td>', 'Good use of a familiar symbol; good lighting, exposure, and color scheme. It''s a little odd having the quotation on the monument readable, since it''s different from your caption. In this one case, I might have considered blurring the type on the monument slightly.', '2003-12-29 00:44:21.000000', NULL, 1),
(524876, 52541, 10170, '<td valign="top">Absolutely stunning.  I love the split into three frames here.</td>', 'Absolutely stunning.  I love the split into three frames here.', '2003-12-29 00:45:24.000000', NULL, 1),
(524877, 52467, 9232, '<td valign="top">Wordy message to me.  Good photo and nice creation.</td>', 'Wordy message to me.  Good photo and nice creation.', '2003-12-29 00:46:45.000000', NULL, 1),
(524878, 52341, 10170, '<td valign="top">The choice of border composition and colour works very well with this photo.  Strange lighting, but it really works well.</td>', 'The choice of border composition and colour works very well with this photo.  Strange lighting, but it really works well.', '2003-12-29 00:47:08.000000', NULL, 1),
(524879, 52384, 9232, '<td valign="top">Great photo but I don''t see anything to help your viewers know the motivation you are trying to impart to them.  Most motivational posters I''ve seen have a word to help the viewer focus and a tagline to explain or expound on the concept.</td>', 'Great photo but I don''t see anything to help your viewers know the motivation you are trying to impart to them.  Most motivational posters I''ve seen have a word to help the viewer focus and a tagline to explain or expound on the concept.', '2003-12-29 00:48:12.000000', NULL, 1),
(524881, 52128, 1031, '<td valign="top">I think the abbreviated title would have been fine, but perhaps you''re wise to not take chances with the voters. Excellent action capture, isolating your subjects from the background. From that angle, I just hope you weren''t trying to referee the match at the same time.</td>', 'I think the abbreviated title would have been fine, but perhaps you''re wise to not take chances with the voters. Excellent action capture, isolating your subjects from the background. From that angle, I just hope you weren''t trying to referee the match at the same time.', '2003-12-29 00:48:24.000000', NULL, 1),
(524882, 52196, 12962, '<td valign="top">So delicious.  The lighting is absolutely perfect.</td>', 'So delicious.  The lighting is absolutely perfect.', '2003-12-29 00:48:36.000000', NULL, 1),
(524884, 52478, 714, '<td valign="top">He is one powerful looking bird!  It is no wonder he was chosen to be  our countries bird.  Excellent shot and good message!  10</td>', 'He is one powerful looking bird!  It is no wonder he was chosen to be  our countries bird.  Excellent shot and good message!  10', '2003-12-29 00:49:52.000000', NULL, 1),
(524885, 52484, 12962, '<td valign="top">Very appropriate picture for the message.  The golden light on the railing leads you to whatever lays beyond, hopefully good stuff.  Good job!</td>', 'Very appropriate picture for the message.  The golden light on the railing leads you to whatever lays beyond, hopefully good stuff.  Good job!', '2003-12-29 00:51:26.000000', NULL, 1),
(524886, 52540, 1031, '<td valign="top">Cool idea with the border, good composition and pose. Color and contrast seem very flat though; I''d like to see how it looks brighter.</td>', 'Cool idea with the border, good composition and pose. Color and contrast seem very flat though; I''d like to see how it looks brighter.', '2003-12-29 00:53:04.000000', NULL, 1),
(524887, 52327, 12962, '<td valign="top">Very nice!  I love this kind of ''bucking the system'' photographs.  Your choice of colors is great and with the black background ... the effect is dramatic.</td>', 'Very nice!  I love this kind of ''bucking the system'' photographs.  Your choice of colors is great and with the black background ... the effect is dramatic.', '2003-12-29 00:53:06.000000', NULL, 1),
(524890, 52540, 9906, '<td valign="top">Ya know what, I really like this one.  It''s by far not perfect, but the most original of all I''ve seen yet and I respect that!<br/>Good luck<br/>TC</td>', 'Ya know what, I really like this one.  It''s by far not perfect, but the most original of all I''ve seen yet and I respect that!Good luckTC', '2003-12-29 00:57:24.000000', NULL, 1),
(524892, 52474, 12962, '<td valign="top">Very fitting ... very beautiful ... and it has been well seen!</td>', 'Very fitting ... very beautiful ... and it has been well seen!', '2003-12-29 00:58:59.000000', NULL, 1),
(524893, 52375, 12962, '<td valign="top">Yesss!</td>', 'Yesss!', '2003-12-29 01:00:42.000000', NULL, 1),
(524894, 52163, 12962, '<td valign="top">Very creative ...</td>', 'Very creative ...', '2003-12-29 01:01:22.000000', NULL, 1),
(524895, 52541, 1031, '<td valign="top">Ironically, dividing the picture into 3 parts emphasizes the simplicity of the subject. I think you picked an unusual background color, but I don''t think I have a better suggestion either.<br/>I like the main type, but I think I''d have used a slightly more calligraphic (but simple) font for the quotation.</td>', 'Ironically, dividing the picture into 3 parts emphasizes the simplicity of the subject. I think you picked an unusual background color, but I don''t think I have a better suggestion either.I like the main type, but I think I''d have used a slightly more calligraphic (but simple) font for the quotation.', '2003-12-29 01:04:54.000000', NULL, 1),
(524896, 52328, 1031, '<td valign="top">The look remarkably like fiber-optic cables, don''t they?</td>', 'The look remarkably like fiber-optic cables, don''t they?', '2003-12-29 01:06:49.000000', NULL, 1),
(524897, 52301, 1031, '<td valign="top">I think the lottery ticket undermines you basic premise somewhat.</td>', 'I think the lottery ticket undermines you basic premise somewhat.', '2003-12-29 01:10:38.000000', NULL, 1),
(524898, 51876, 1031, '<td valign="top">Yikes, that looks very bad. It will probably motivate me to continue avoiding driving big-rigs.</td>', 'Yikes, that looks very bad. It will probably motivate me to continue avoiding driving big-rigs.', '2003-12-29 01:12:46.000000', NULL, 1),
(524899, 52271, 10170, '<td valign="top">A lot of effort obviously went into this, nice work.</td>', 'A lot of effort obviously went into this, nice work.', '2003-12-29 01:14:51.000000', NULL, 1),
(524900, 52531, 12962, '<td valign="top">Very apropos ... symbolism is strong and universal ...  colors are great ... black background enhances the main elements.</td>', 'Very apropos ... symbolism is strong and universal ...  colors are great ... black background enhances the main elements.', '2003-12-29 01:14:58.000000', NULL, 1),
(524901, 52534, 1031, '<td valign="top">Good use of panoramic layout. I''m trying to decide if I''d want those eyes at 3 feet across staring from my office wall .</td>', 'Good use of panoramic layout. I''m trying to decide if I''d want those eyes at 3 feet across staring from my office wall .', '2003-12-29 01:15:45.000000', NULL, 1),
(524903, 52176, 12962, '<td valign="top">I love the photograph, macro is excellent, DOF is good,  but, pardon me because it just might be me, I am not able to connect the message with the picture.</td>', 'I love the photograph, macro is excellent, DOF is good,  but, pardon me because it just might be me, I am not able to connect the message with the picture.', '2003-12-29 01:16:48.000000', NULL, 1),
(524904, 51884, 1031, '<td valign="top">Hmm ... pushing the boundaries through sarcasm?  Reminds me of the joke/Tshirt:<br/>"Drinking problem? I don''t have a drinking problem. I drink, I get drunk, I fall down. No problem."</td>', 'Hmm ... pushing the boundaries through sarcasm?  Reminds me of the joke/Tshirt:"Drinking problem? I don''t have a drinking problem. I drink, I get drunk, I fall down. No problem."', '2003-12-29 01:19:32.000000', NULL, 1),
(524905, 52176, 10170, '<td valign="top">Love the photo.  The text lets it down slightly as it is hard to read and could be a little sharper.</td>', 'Love the photo.  The text lets it down slightly as it is hard to read and could be a little sharper.', '2003-12-29 01:21:00.000000', NULL, 1),
(524906, 52181, 12962, '<td valign="top">So true ... YOUR patience was rewarded with this beautiful photograph :-).  Beautiful composition, great colors, and excellent lighting (focused on the bird) ...</td>', 'So true ... YOUR patience was rewarded with this beautiful photograph :-).  Beautiful composition, great colors, and excellent lighting (focused on the bird) ...', '2003-12-29 01:21:17.000000', NULL, 1),
(524907, 52560, 1031, '<td valign="top">... and let me have 18 hours a day set aside to catnap. As a poster I think the photo could be a bit smaller (or border bigger).</td>', '... and let me have 18 hours a day set aside to catnap. As a poster I think the photo could be a bit smaller (or border bigger).', '2003-12-29 01:21:47.000000', NULL, 1),
(524908, 51884, 10170, '<td valign="top">*laugh*  Fun photo, could be out of a (warped) magasine.  Nice work.</td>', '*laugh*  Fun photo, could be out of a (warped) magasine.  Nice work.', '2003-12-29 01:22:08.000000', NULL, 1),
(524909, 51848, 10170, '<td valign="top">Nice clear shot, great lighting.  Fits the challenge well and the title is very appropriate to the image.  Nice work.</td>', 'Nice clear shot, great lighting.  Fits the challenge well and the title is very appropriate to the image.  Nice work.', '2003-12-29 01:23:21.000000', NULL, 1),
(524910, 52532, 12962, '<td valign="top">Nice, appropriate picture for your message and good action shot picture we have here.  I also like your use of red to pull in your readers.   I just wish your text is a little bit bigger for feeble-eyed seniors like me.</td>', 'Nice, appropriate picture for your message and good action shot picture we have here.  I also like your use of red to pull in your readers.   I just wish your text is a little bit bigger for feeble-eyed seniors like me.', '2003-12-29 01:23:55.000000', NULL, 1),
(524911, 52341, 1031, '<td valign="top">I taking it your camera survived the spray? I think I''d also try a little lighter color for the large intermediate matte since the dog is kind of low contrast..</td>', 'I taking it your camera survived the spray? I think I''d also try a little lighter color for the large intermediate matte since the dog is kind of low contrast..', '2003-12-29 01:24:16.000000', NULL, 1),
(524912, 52512, 10170, '<td valign="top">Stunning photo.  Text could be a little clearer is my only negative here.  Great shot.</td>', 'Stunning photo.  Text could be a little clearer is my only negative here.  Great shot.', '2003-12-29 01:26:38.000000', NULL, 1),
(524913, 51901, 10170, '<td valign="top">Stunning and so very simple.  Love it.  Good choice of such a large border.</td>', 'Stunning and so very simple.  Love it.  Good choice of such a large border.', '2003-12-29 01:29:24.000000', NULL, 1),
(524914, 52478, 1031, '<td valign="top">That kind of pinko feel-good namby-pamby philosophy will get you nowhere in this land of spin-doctors and the pre-emptive strike. &lt;/sarcasm&gt;<br/>Great shot of the eagle; hope your poster gets wide distribution.</td>', 'That kind of pinko feel-good namby-pamby philosophy will get you nowhere in this land of spin-doctors and the pre-emptive strike. </sarcasm>Great shot of the eagle; hope your poster gets wide distribution.', '2003-12-29 01:29:31.000000', NULL, 1),
(524915, 52501, 10170, '<td valign="top">Like the photo, but the coloured text really detracts from it.</td>', 'Like the photo, but the coloured text really detracts from it.', '2003-12-29 01:31:34.000000', NULL, 1),
(524916, 52364, 12962, '<td valign="top">Excellence!  The picture and your message are so fitting.  The picture itself is beautifully done ... with the diagonals leading to the person who seem to be very determined to reach the peak.  Well done!</td>', 'Excellence!  The picture and your message are so fitting.  The picture itself is beautifully done ... with the diagonals leading to the person who seem to be very determined to reach the peak.  Well done!', '2003-12-29 01:32:54.000000', NULL, 1),
(524917, 52510, 10170, '<td valign="top">Can''t make a connection here with this being a motivational poster, either by the pic or title.  How does this motivate?  PM and explain if you you like.</td>', 'Can''t make a connection here with this being a motivational poster, either by the pic or title.  How does this motivate?  PM and explain if you you like.', '2003-12-29 01:34:04.000000', NULL, 1),
(524918, 52499, 10170, '<td valign="top">Love the photo.  The text could be a lot sharper.</td>', 'Love the photo.  The text could be a lot sharper.', '2003-12-29 01:35:25.000000', NULL, 1),
(524919, 52521, 10170, '<td valign="top">Beautiful shot, the DOF works really well and the main flower is lovely and crisp.</td>', 'Beautiful shot, the DOF works really well and the main flower is lovely and crisp.', '2003-12-29 01:36:28.000000', NULL, 1),
(524921, 52530, 10170, '<td valign="top">I like it, but think I would have preferred the colours slightly more natural, as the pink looks a little fake.</td>', 'I like it, but think I would have preferred the colours slightly more natural, as the pink looks a little fake.', '2003-12-29 01:40:23.000000', NULL, 1),
(524922, 52378, 10170, '<td valign="top">Nicely done, the lighting here is great.</td>', 'Nicely done, the lighting here is great.', '2003-12-29 01:40:49.000000', NULL, 1),
(524923, 52532, 10170, '<td valign="top">Excellent action shot!  The text spoils it a little as it is too small to read, but no marks deducted as if were poster size I am sure it would be perfectly readable (and this was about posters)</td>', 'Excellent action shot!  The text spoils it a little as it is too small to read, but no marks deducted as if were poster size I am sure it would be perfectly readable (and this was about posters)', '2003-12-29 01:43:26.000000', NULL, 1),
(524929, 52474, 14781, '<td valign="top">Truely magnificint!!!  Breathtaking photography!</td>', 'Truely magnificint!!!  Breathtaking photography!', '2003-12-29 01:56:00.000000', NULL, 1),
(524930, 52444, 14781, '<td valign="top">How often we take for granted the simple things in life...  Good capture!</td>', 'How often we take for granted the simple things in life...  Good capture!', '2003-12-29 01:56:50.000000', NULL, 1),
(524931, 52163, 11034, '<td valign="top">ja jaja. You really make my smile. I am Accountant.  :.)<br/>Good luck.</td>', 'ja jaja. You really make my smile. I am Accountant.  :.)Good luck.', '2003-12-29 01:56:58.000000', NULL, 1),
(524932, 52530, 14781, '<td valign="top">I am awestruck at this photo! It is breathtaking, beautiful!</td>', 'I am awestruck at this photo! It is breathtaking, beautiful!', '2003-12-29 01:57:31.000000', NULL, 1),
(524940, 52531, 14891, '<td valign="top">looks heavily edited with photoshop</td>', 'looks heavily edited with photoshop', '2003-12-29 02:38:38.000000', NULL, 1),
(524942, 52414, 14891, '<td valign="top">this would be a superb shot if it didn''t have those words so big.</td>', 'this would be a superb shot if it didn''t have those words so big.', '2003-12-29 02:41:57.000000', NULL, 1),
(524943, 52281, 14891, '<td valign="top">heavily edited...</td>', 'heavily edited...', '2003-12-29 02:43:47.000000', NULL, 1),
(524945, 52499, 14891, '<td valign="top">can not read the text</td>', 'can not read the text', '2003-12-29 02:45:18.000000', NULL, 1),
(524946, 52455, 14891, '<td valign="top">????</td>', '????', '2003-12-29 02:46:17.000000', NULL, 1),
(524951, 52530, 10275, '<td valign="top">The photo is absolutely gorgeous. The colours are spectacular and the clarity is very good for en evening shot. But you went way over board with the borders. The thin one around the whole frame is fine, but the shocking pink thick border around the image and around the text could have been totally excluded and you would still have a very powerful poster. It kind of spoiled it for me.</td>', 'The photo is absolutely gorgeous. The colours are spectacular and the clarity is very good for en evening shot. But you went way over board with the borders. The thin one around the whole frame is fine, but the shocking pink thick border around the image and around the text could have been totally excluded and you would still have a very powerful poster. It kind of spoiled it for me.', '2003-12-29 03:09:14.000000', NULL, 1),
(524954, 52415, 10275, '<td valign="top">Very clever idea. LIke the composition and design. The only thing I am not so sure about is the yellowish cast the whole image has. Otherwise well done.</td>', 'Very clever idea. LIke the composition and design. The only thing I am not so sure about is the yellowish cast the whole image has. Otherwise well done.', '2003-12-29 03:10:14.000000', NULL, 1),
(524955, 51876, 15354, '<td valign="top">Dude, that''s horrible. Is the driver OK?</td>', 'Dude, that''s horrible. Is the driver OK?', '2003-12-29 03:10:39.000000', NULL, 1),
(524956, 52484, 10275, '<td valign="top">I am really into bridges, so this one is in my top list. Wonderful perspective and the glow it has ads additional touch to the hope. I also like the text very much (the font selection). Very well done.</td>', 'I am really into bridges, so this one is in my top list. Wonderful perspective and the glow it has ads additional touch to the hope. I also like the text very much (the font selection). Very well done.', '2003-12-29 03:12:35.000000', NULL, 1),
(524958, 52392, 10275, '<td valign="top">Superb shot. The clarity is... well, eagle sharp :-) You''ve done great job with this image. It is one of the few textless posters, but the quality of the photo really speaks for itself in this case. Top ten finish I predict.</td>', 'Superb shot. The clarity is... well, eagle sharp :-) You''ve done great job with this image. It is one of the few textless posters, but the quality of the photo really speaks for itself in this case. Top ten finish I predict.', '2003-12-29 03:14:47.000000', NULL, 1),
(524959, 52477, 10275, '<td valign="top">One of my top picks. I love the humor of this shot. My only suggesion would be to have a tiny big more space on the top and less on the bottom which would bring the text up a bit. The shot has a great perspective and sharpness. Well done.</td>', 'One of my top picks. I love the humor of this shot. My only suggesion would be to have a tiny big more space on the top and less on the bottom which would bring the text up a bit. The shot has a great perspective and sharpness. Well done.', '2003-12-29 03:16:50.000000', NULL, 1),
(524961, 52163, 10275, '<td valign="top">This is funny. Good shot of an ordinary object. I am glad it has just a simple border which does not distract. I would have picked a simpler font, but you pulled it off OK. Definitely a top contender.</td>', 'This is funny. Good shot of an ordinary object. I am glad it has just a simple border which does not distract. I would have picked a simpler font, but you pulled it off OK. Definitely a top contender.', '2003-12-29 03:18:24.000000', NULL, 1),
(524962, 52459, 10275, '<td valign="top">Gorgeous shot. Lovely sunset/sunrise colours. Great perspective and depth of field. I just don''t like the text on the top. It would have been cleaner on the bottom, maby reversed or lighter colour. On top it creates certain inbalance (the top left seem a bit heavy compared to the bottom right of the image).</td>', 'Gorgeous shot. Lovely sunset/sunrise colours. Great perspective and depth of field. I just don''t like the text on the top. It would have been cleaner on the bottom, maby reversed or lighter colour. On top it creates certain inbalance (the top left seem a bit heavy compared to the bottom right of the image).', '2003-12-29 03:20:13.000000', NULL, 1),
(524963, 52467, 10275, '<td valign="top">Gorgeous snowflake macro. Love it in b&amp;w. It is simple, but bery beautiful. The only small thing I don''t like is that the text is way too big. It could have been a nudge smaller, because it is reversed white on black, it is very powerful even if were smaller. The font you picked is nice for this poster. Overall one of my favourites in this challenge.</td>', 'Gorgeous snowflake macro. Love it in b&w. It is simple, but bery beautiful. The only small thing I don''t like is that the text is way too big. It could have been a nudge smaller, because it is reversed white on black, it is very powerful even if were smaller. The font you picked is nice for this poster. Overall one of my favourites in this challenge.', '2003-12-29 03:22:32.000000', NULL, 1),
(524964, 52490, 10275, '<td valign="top">Love this poster. Simple, but clean and beautiful. Gees are truly smart birds. We should learn from them about teamwork. Great clarity and sharpness. Like the blue text, but the purple border should have been similar shade of blue (it''s kind of out of place). Otherwise very well done.</td>', 'Love this poster. Simple, but clean and beautiful. Gees are truly smart birds. We should learn from them about teamwork. Great clarity and sharpness. Like the blue text, but the purple border should have been similar shade of blue (it''s kind of out of place). Otherwise very well done.', '2003-12-29 03:24:17.000000', NULL, 1),
(524965, 52539, 10275, '<td valign="top">Beautiful, simple, clean. Stands out from some of the more busier posters. Colours are very nice, lovely contrast. Border OK. The text (the main word) could have been a bit larger (but just a tiny bit). You''ve done great job with this.</td>', 'Beautiful, simple, clean. Stands out from some of the more busier posters. Colours are very nice, lovely contrast. Border OK. The text (the main word) could have been a bit larger (but just a tiny bit). You''ve done great job with this.', '2003-12-29 03:25:46.000000', NULL, 1),
(524966, 51848, 10275, '<td valign="top">Great concept, well designed. Like the ghosted word under the grey text. Image is dead on. Lovely DOF and composition in the photo. Simple and clean. Love it.</td>', 'Great concept, well designed. Like the ghosted word under the grey text. Image is dead on. Lovely DOF and composition in the photo. Simple and clean. Love it.', '2003-12-29 03:26:37.000000', NULL, 1),
(524967, 51971, 6130, '<td valign="top">Very good.</td>', 'Very good.', '2003-12-29 03:27:54.000000', NULL, 1),
(524968, 52536, 10275, '<td valign="top">I really like the way I am drawn to the face and the eye. Great contrast of the red hair and the grey coat. Photo is very well done, the text could have been a tiny bit smaller and along the bottom. On the top as it is, it throws the image a bit out of kilt. Otherwise well done.</td>', 'I really like the way I am drawn to the face and the eye. Great contrast of the red hair and the grey coat. Photo is very well done, the text could have been a tiny bit smaller and along the bottom. On the top as it is, it throws the image a bit out of kilt. Otherwise well done.', '2003-12-29 03:28:51.000000', NULL, 1),
(524969, 51919, 10275, '<td valign="top">Beautiful photograph, but the fonts is kind of distorted and fuzzy. Also you could have given the text more space around it to separate the image from the text. Posters usually don''t have borders on the edges. The middle border would have been enough. But the photo itself is great!</td>', 'Beautiful photograph, but the fonts is kind of distorted and fuzzy. Also you could have given the text more space around it to separate the image from the text. Posters usually don''t have borders on the edges. The middle border would have been enough. But the photo itself is great!', '2003-12-29 03:30:46.000000', NULL, 1),
(524970, 51901, 10275, '<td valign="top">Very classy. Simple, yet powerful. Interesting DOF. Love the text (the font). Well done.</td>', 'Very classy. Simple, yet powerful. Interesting DOF. Love the text (the font). Well done.', '2003-12-29 03:31:31.000000', NULL, 1),
(524971, 52474, 10275, '<td valign="top">Beautiful sunset/sunrise colours. The lighter part of the image is a bit overexposed, but the rest of the image is good. I would have loved to see the text below the image as a poster, but no marks taken for that. Still one of my picks.</td>', 'Beautiful sunset/sunrise colours. The lighter part of the image is a bit overexposed, but the rest of the image is good. I would have loved to see the text below the image as a poster, but no marks taken for that. Still one of my picks.', '2003-12-29 03:33:19.000000', NULL, 1),
(524972, 52479, 10275, '<td valign="top">Interesting eery photo. It almost looks like a tree from a movie stage, like I am going to see an elf in the branches... How true the text is!  Well done.</td>', 'Interesting eery photo. It almost looks like a tree from a movie stage, like I am going to see an elf in the branches... How true the text is!  Well done.', '2003-12-29 03:35:12.000000', NULL, 1),
(524973, 52181, 10275, '<td valign="top">Photo is superb. Colours look very natural. But the font is kind of wild and unseen in pro posters. But if that''s your style, then go for it. Well done photo.</td>', 'Photo is superb. Colours look very natural. But the font is kind of wild and unseen in pro posters. But if that''s your style, then go for it. Well done photo.', '2003-12-29 03:36:40.000000', NULL, 1),
(524974, 52560, 10275, '<td valign="top">Such a sweet photo. Love the detail of the fur. Great that it is kind of white all over as it really portrays the peacefulness. I am not too keen on the font you used, but over all it is ok. The outer border could have been dropped for simplicity. Well done.</td>', 'Such a sweet photo. Love the detail of the fur. Great that it is kind of white all over as it really portrays the peacefulness. I am not too keen on the font you used, but over all it is ok. The outer border could have been dropped for simplicity. Well done.', '2003-12-29 03:38:17.000000', NULL, 1),
(524975, 52366, 10275, '<td valign="top">Nice framing. The colours and tones are on the darker side, but I guess this was too far for a flash to be of any use. The aerial perspective is nice.</td>', 'Nice framing. The colours and tones are on the darker side, but I guess this was too far for a flash to be of any use. The aerial perspective is nice.', '2003-12-29 03:39:36.000000', NULL, 1),
(524977, 52327, 10275, '<td valign="top">Wow, I''ve never seen white M&amp;Ms before. Cute concept. Simple colour with good effect. It''s a bit too tightly cropped for my taste and more space around the text would have helped. It feels tiny bit claustrophobic.</td>', 'Wow, I''ve never seen white M&Ms before. Cute concept. Simple colour with good effect. It''s a bit too tightly cropped for my taste and more space around the text would have helped. It feels tiny bit claustrophobic.', '2003-12-29 03:42:44.000000', NULL, 1),
(524978, 52364, 10275, '<td valign="top">The text really fits the theme of the photo. This photo would have been great in b&amp;w as it has very little colour in it. But the sky is kind of nice too. Did you use hight speed film? It appears a bit grainy on the darker portions of the photo. But I still like it a lot.</td>', 'The text really fits the theme of the photo. This photo would have been great in b&w as it has very little colour in it. But the sky is kind of nice too. Did you use hight speed film? It appears a bit grainy on the darker portions of the photo. But I still like it a lot.', '2003-12-29 03:44:33.000000', NULL, 1),
(524979, 52507, 10275, '<td valign="top">Great teamwork shot. Love it in b&amp;w. I am not sure why, but I see a line through the text for some reason. I don''t know if this was intentional, but it looks kind of strange. The font works OK. The border could have been simpler for this image. But well done otherwise.</td>', 'Great teamwork shot. Love it in b&w. I am not sure why, but I see a line through the text for some reason. I don''t know if this was intentional, but it looks kind of strange. The font works OK. The border could have been simpler for this image. But well done otherwise.', '2003-12-29 03:45:54.000000', NULL, 1),
(524980, 52460, 10275, '<td valign="top">Beautiful photo, but really ugly border (sorry). The colours are great, so is the sharpness. This is in one in the million kind of shot, where you catch the bird in the perfect moment of stepping down. The text is kind of lost in the image. It could have been better on the bottom of the black frame reversed. The photo itself is very good, but the framing really spoiled it.</td>', 'Beautiful photo, but really ugly border (sorry). The colours are great, so is the sharpness. This is in one in the million kind of shot, where you catch the bird in the perfect moment of stepping down. The text is kind of lost in the image. It could have been better on the bottom of the black frame reversed. The photo itself is very good, but the framing really spoiled it.', '2003-12-29 03:48:48.000000', NULL, 1),
(524981, 52378, 10275, '<td valign="top">Clean, simple, beautifully designed. Not so sure about the brown colour and the pinkish smaller text. But the photo itself is great and fits your caption perfectly.</td>', 'Clean, simple, beautifully designed. Not so sure about the brown colour and the pinkish smaller text. But the photo itself is great and fits your caption perfectly.', '2003-12-29 03:49:46.000000', NULL, 1),
(524983, 52552, 10275, '<td valign="top">Good idea and concept, but the poster is kind of very busy. The torn border makes it even messier and the text running into the coins throws it out of balance. The text could have been smaller and with gentler shadow. I don''t know what kind of lighting you use, but the glare on the coins further distracts from the whole image. Sometimes it''s good to place a thin piece of tissue paper between the lightsource and the subject to diffuse hard light. But you have a unique ideas, so don''t give up.</td>', 'Good idea and concept, but the poster is kind of very busy. The torn border makes it even messier and the text running into the coins throws it out of balance. The text could have been smaller and with gentler shadow. I don''t know what kind of lighting you use, but the glare on the coins further distracts from the whole image. Sometimes it''s good to place a thin piece of tissue paper between the lightsource and the subject to diffuse hard light. But you have a unique ideas, so don''t give up.', '2003-12-29 03:53:27.000000', NULL, 1),
(524984, 52444, 10275, '<td valign="top">One of the most emotional posters in this run. I wouldn''t change a thing about the photo itself, but the frame could have been simpler for this kind of message. Also, I think it would have been even more powerful in b&amp;w form. But don''t get me wrong, I really love this poster.</td>', 'One of the most emotional posters in this run. I wouldn''t change a thing about the photo itself, but the frame could have been simpler for this kind of message. Also, I think it would have been even more powerful in b&w form. But don''t get me wrong, I really love this poster.', '2003-12-29 03:55:00.000000', NULL, 1),
(524985, 52534, 10275, '<td valign="top">Sweet picture. Beautiful colours and cute composition. But it is not as sharp as I would expect from this kind of close up shot. Also, you could have edited out the glare in the left eye and the redness in the baby''s pupils.</td>', 'Sweet picture. Beautiful colours and cute composition. But it is not as sharp as I would expect from this kind of close up shot. Also, you could have edited out the glare in the left eye and the redness in the baby''s pupils.', '2003-12-29 03:57:15.000000', NULL, 1),
(524986, 52502, 10275, '<td valign="top">I do not get this? What is it supposed to motivate me towards? Eating rats or having a snake? Could you please explain. Photo itself is great.</td>', 'I do not get this? What is it supposed to motivate me towards? Eating rats or having a snake? Could you please explain. Photo itself is great.', '2003-12-29 03:58:44.000000', NULL, 1),
(524987, 52521, 10275, '<td valign="top">Great flower shot. Lovely colours and composition of the image. But I would have placed the text lower towards the bottom. You will rarely see a text in the middle of a poster especially when it''s competing for attention with the main subject.</td>', 'Great flower shot. Lovely colours and composition of the image. But I would have placed the text lower towards the bottom. You will rarely see a text in the middle of a poster especially when it''s competing for attention with the main subject.', '2003-12-29 04:01:06.000000', NULL, 1),
(524989, 52366, 6130, '<td valign="top">Beautiful and very good.</td>', 'Beautiful and very good.', '2003-12-29 04:45:32.000000', NULL, 1),
(524990, 52378, 6130, '<td valign="top">Very,very good.</td>', 'Very,very good.', '2003-12-29 04:46:20.000000', NULL, 1),
(524991, 52478, 6130, '<td valign="top">Fantastic.</td>', 'Fantastic.', '2003-12-29 04:47:01.000000', NULL, 1),
(524992, 52484, 6130, '<td valign="top">Nice and I like it.</td>', 'Nice and I like it.', '2003-12-29 04:48:06.000000', NULL, 1),
(524993, 52540, 6130, '<td valign="top">I like this.</td>', 'I like this.', '2003-12-29 04:48:31.000000', NULL, 1),
(524994, 51919, 6130, '<td valign="top">This is very good.</td>', 'This is very good.', '2003-12-29 04:49:49.000000', NULL, 1),
(524995, 52472, 10275, '<td valign="top">Nice concept and shot. Fits perfectly with the challenge and with the text. But I would have put the text completely to the bottom of the poster. This way it kind of floats. Also the border is somehow not fitting with this image, either have a soft border or a hard one. Combining both creates unbalance to me.</td>', 'Nice concept and shot. Fits perfectly with the challenge and with the text. But I would have put the text completely to the bottom of the poster. This way it kind of floats. Also the border is somehow not fitting with this image, either have a soft border or a hard one. Combining both creates unbalance to me.', '2003-12-29 04:50:42.000000', NULL, 1),
(524996, 52536, 6130, '<td valign="top">I hope this win.10</td>', 'I hope this win.10', '2003-12-29 04:51:10.000000', NULL, 1),
(524997, 52537, 10275, '<td valign="top">Composition is good, concept ok, but how is it supposed to motivate me? The word UNITE could have been a bit smaller (less tall). Too bad the front hand is not in focus as the rest of the image is. If this is a child''s shot - well done. If it is an adult who created this - keep trying.</td>', 'Composition is good, concept ok, but how is it supposed to motivate me? The word UNITE could have been a bit smaller (less tall). Too bad the front hand is not in focus as the rest of the image is. If this is a child''s shot - well done. If it is an adult who created this - keep trying.', '2003-12-29 04:52:58.000000', NULL, 1),
(524998, 52384, 6130, '<td valign="top">Wonderful message.</td>', 'Wonderful message.', '2003-12-29 04:54:00.000000', NULL, 1),
(524999, 52544, 6130, '<td valign="top">Lovely and very good.</td>', 'Lovely and very good.', '2003-12-29 04:55:08.000000', NULL, 1),
(525000, 51884, 10275, '<td valign="top">OK, this is a joke I guess. I wouldn''t want to be motivated into drinking :-)) Even a snapshot like this can be lulled into serious looking poster with some heavy border and red text I guess.  The red text is pixelated and why is the image so small. Anyway, you met the challenge, but it''s not your best.</td>', 'OK, this is a joke I guess. I wouldn''t want to be motivated into drinking :-)) Even a snapshot like this can be lulled into serious looking poster with some heavy border and red text I guess.  The red text is pixelated and why is the image so small. Anyway, you met the challenge, but it''s not your best.', '2003-12-29 04:55:56.000000', NULL, 1),
(525001, 52341, 10275, '<td valign="top">Amazing frozen action shot. But very ugly border. I am sorry to be so direct, but the border totally turned me away from otherwise interesting photo.</td>', 'Amazing frozen action shot. But very ugly border. I am sorry to be so direct, but the border totally turned me away from otherwise interesting photo.', '2003-12-29 04:57:06.000000', NULL, 1),
(525002, 52541, 6130, '<td valign="top">Wonderful.</td>', 'Wonderful.', '2003-12-29 04:57:20.000000', NULL, 1),
(525003, 52490, 6130, '<td valign="top">Lovely pic and message.</td>', 'Lovely pic and message.', '2003-12-29 04:58:40.000000', NULL, 1),
(525004, 52414, 10275, '<td valign="top">Interesting idea about the balancing act. But the text is so very ugly. If this was a joke, then sorry. But if you are serious about this motivating someone, I think you''ve just succeeded to scare them away.</td>', 'Interesting idea about the balancing act. But the text is so very ugly. If this was a joke, then sorry. But if you are serious about this motivating someone, I think you''ve just succeeded to scare them away.', '2003-12-29 04:59:13.000000', NULL, 1),
(525005, 52542, 6130, '<td valign="top">Fantastic.</td>', 'Fantastic.', '2003-12-29 05:02:20.000000', NULL, 1),
(525006, 52557, 10275, '<td valign="top">Great classic shot and concept.</td>', 'Great classic shot and concept.', '2003-12-29 05:04:29.000000', NULL, 1),
(525007, 52561, 10275, '<td valign="top">Beautiful clarity, but a bit tightly cropped.</td>', 'Beautiful clarity, but a bit tightly cropped.', '2003-12-29 05:04:52.000000', NULL, 1),
(525008, 52361, 10275, '<td valign="top">Great sense of perspective, but a bit soft for me. The darker parts need brightening.</td>', 'Great sense of perspective, but a bit soft for me. The darker parts need brightening.', '2003-12-29 05:05:36.000000', NULL, 1),
(525009, 52535, 10275, '<td valign="top">Beautiful ocean scenery. The waves breaking on the rocks are superb touch. I am not so sure about the slanted font though.</td>', 'Beautiful ocean scenery. The waves breaking on the rocks are superb touch. I am not so sure about the slanted font though.', '2003-12-29 05:06:19.000000', NULL, 1),
(525010, 51901, 6130, '<td valign="top">Simple and very good.</td>', 'Simple and very good.', '2003-12-29 05:06:20.000000', NULL, 1),
(525011, 52542, 10275, '<td valign="top">Very well done.</td>', 'Very well done.', '2003-12-29 05:06:52.000000', NULL, 1),
(525012, 52538, 10275, '<td valign="top">Wow, great perspective and depth. Good clarity and sharpness. Love the font on the bottom, but the top one is a bit too heavy for my taste. It is usually the other way around. Lighter design components go toward the top and heavier towrads the bottom. Otherwise well done.</td>', 'Wow, great perspective and depth. Good clarity and sharpness. Love the font on the bottom, but the top one is a bit too heavy for my taste. It is usually the other way around. Lighter design components go toward the top and heavier towrads the bottom. Otherwise well done.', '2003-12-29 05:08:18.000000', NULL, 1),
(525013, 52384, 10275, '<td valign="top">Oh, this is so cute. Such a great catch. Soft beautiful colours. A bit on the softer side of focusing, but in this case I guess it''s ok. Love the blurred background. Composition right on.</td>', 'Oh, this is so cute. Such a great catch. Soft beautiful colours. A bit on the softer side of focusing, but in this case I guess it''s ok. Love the blurred background. Composition right on.', '2003-12-29 05:09:28.000000', NULL, 1),
(525014, 52238, 10275, '<td valign="top">Beautiful soft water effect, great depth and perspective, good composition. I would bump up the colours a bit (maby add some soft reddish tones on the rocks).</td>', 'Beautiful soft water effect, great depth and perspective, good composition. I would bump up the colours a bit (maby add some soft reddish tones on the rocks).', '2003-12-29 05:10:23.000000', NULL, 1),
(525015, 52521, 6130, '<td valign="top">Great.</td>', 'Great.', '2003-12-29 05:10:42.000000', NULL, 1),
(525016, 52123, 10275, '<td valign="top">Composition is very good, but I would have give the text more space and the border a bit thinner.</td>', 'Composition is very good, but I would have give the text more space and the border a bit thinner.', '2003-12-29 05:10:52.000000', NULL, 1),
(525017, 52136, 10275, '<td valign="top">Gorgeous sunset colours.  Like the slight tilt of it all. But the image appears kind of small. The text should be a bit bigger as well for impact.</td>', 'Gorgeous sunset colours.  Like the slight tilt of it all. But the image appears kind of small. The text should be a bit bigger as well for impact.', '2003-12-29 05:11:41.000000', NULL, 1),
(525018, 52532, 10275, '<td valign="top">Great frozen action shot. Love the colour contrast between the greyish water and the boat. The quote text is a bit too small to be legible in this context (but I know it''s the same like your title). Looks like pro poster. Well done.</td>', 'Great frozen action shot. Love the colour contrast between the greyish water and the boat. The quote text is a bit too small to be legible in this context (but I know it''s the same like your title). Looks like pro poster. Well done.', '2003-12-29 05:13:24.000000', NULL, 1),
(525019, 52526, 10275, '<td valign="top">Lovely closeup of a violin. Although it appears to be floating in space, it is clean and simply beautiful image.</td>', 'Lovely closeup of a violin. Although it appears to be floating in space, it is clean and simply beautiful image.', '2003-12-29 05:14:08.000000', NULL, 1),
(525020, 52196, 10275, '<td valign="top">Great shot for lovers of golf. My husband would thank you for this one. Great blurred action behind a completely still ball. The glare on the ball is a bit distracting from the rest of the clean look of your poster. The border is good.</td>', 'Great shot for lovers of golf. My husband would thank you for this one. Great blurred action behind a completely still ball. The glare on the ball is a bit distracting from the rest of the clean look of your poster. The border is good.', '2003-12-29 05:15:11.000000', NULL, 1),
(525021, 52550, 10275, '<td valign="top">Beautiful sunset shot (from a plane?)... Lovely sea of blue clouds. It''s a bit grainy, but I guess you had to use higher speed of ISO. The title fits very well with the image.</td>', 'Beautiful sunset shot (from a plane?)... Lovely sea of blue clouds. It''s a bit grainy, but I guess you had to use higher speed of ISO. The title fits very well with the image.', '2003-12-29 05:16:18.000000', NULL, 1),
(525023, 51995, 10275, '<td valign="top">Amazing shot of the man. Love the reflection  and the arrows add a nice touch. But the text is too overpowering for the image.</td>', 'Amazing shot of the man. Love the reflection  and the arrows add a nice touch. But the text is too overpowering for the image.', '2003-12-29 05:18:33.000000', NULL, 1),
(525024, 52512, 10275, '<td valign="top">This is so very gorgeous photo. The reflections in the shallow water are just superb. But the text is a bit messy and unclear. Simpler font might have helped. Without the text - one of the top images in this challenge.</td>', 'This is so very gorgeous photo. The reflections in the shallow water are just superb. But the text is a bit messy and unclear. Simpler font might have helped. Without the text - one of the top images in this challenge.', '2003-12-29 05:20:11.000000', NULL, 1),
(525025, 52478, 10275, '<td valign="top">Beautiful photo. Second eagle in this challenge, yet equally well done. I am not too sure about the text being so on the left and the font is kind of messy. But the photo itself is great.</td>', 'Beautiful photo. Second eagle in this challenge, yet equally well done. I am not too sure about the text being so on the left and the font is kind of messy. But the photo itself is great.', '2003-12-29 05:21:31.000000', NULL, 1),
(525026, 52328, 10275, '<td valign="top">Great concept and idea... The shot is well done. I am not too keen about big text over an image, it could have been interesting to the right of the brush.</td>', 'Great concept and idea... The shot is well done. I am not too keen about big text over an image, it could have been interesting to the right of the brush.', '2003-12-29 05:22:23.000000', NULL, 1),
(525027, 52503, 10275, '<td valign="top">Lovely door shot. Great colour and good composition. It''s a bit soft, but holds well.</td>', 'Lovely door shot. Great colour and good composition. It''s a bit soft, but holds well.', '2003-12-29 05:23:18.000000', NULL, 1),
(525028, 52128, 10275, '<td valign="top">Great frozen action shot. Colours are nice for an indoor shot. The photo is fine, but the text is a bit childish. I know you are portraying children, but cleaner font would have helped to make it look like a pro motivational poster.</td>', 'Great frozen action shot. Colours are nice for an indoor shot. The photo is fine, but the text is a bit childish. I know you are portraying children, but cleaner font would have helped to make it look like a pro motivational poster.', '2003-12-29 05:25:16.000000', NULL, 1),
(525029, 52215, 10275, '<td valign="top">Photo is very nice, but kind of small for the large red mat. The text totally overpowers the image which should be the main focus. My eyes immediately go the the large &amp;. If you are centering the text, centre both lines, or make them both flush to the left. Mixing it up together creates chaotic message. Your poster is intense as you may have intended, but cleaning it up a bit would have made it into a very well done poster.</td>', 'Photo is very nice, but kind of small for the large red mat. The text totally overpowers the image which should be the main focus. My eyes immediately go the the large &. If you are centering the text, centre both lines, or make them both flush to the left. Mixing it up together creates chaotic message. Your poster is intense as you may have intended, but cleaning it up a bit would have made it into a very well done poster.', '2003-12-29 05:27:49.000000', NULL, 1),
(525030, 52465, 10275, '<td valign="top">This is great shot. The text fits well with the theme of the photo. The colours are kind of drabby and the image is a bit grainy. Composition is good, could be a bit brighter. In this case it was not such a good idea to put the text up on the top, it kind of creates unbalance. It would have been nicer reversed on the bottom over the dark part masking some of the messiness of the deck.</td>', 'This is great shot. The text fits well with the theme of the photo. The colours are kind of drabby and the image is a bit grainy. Composition is good, could be a bit brighter. In this case it was not such a good idea to put the text up on the top, it kind of creates unbalance. It would have been nicer reversed on the bottom over the dark part masking some of the messiness of the deck.', '2003-12-29 05:30:59.000000', NULL, 1),
(525032, 52454, 10275, '<td valign="top">Cutie face. A bit oversaturated on the bottom left. But the face loks ok. I am not sure if I would consider this motivational poster, but for a shot of a kid is kind of nice.</td>', 'Cutie face. A bit oversaturated on the bottom left. But the face loks ok. I am not sure if I would consider this motivational poster, but for a shot of a kid is kind of nice.', '2003-12-29 05:32:02.000000', NULL, 1),
(525033, 52559, 10275, '<td valign="top">Nice sillueted composition. The font is kind of boring though. The top line should be a bit bolder and the bottom text a bit smaller for nice visual. Photo is nice.</td>', 'Nice sillueted composition. The font is kind of boring though. The top line should be a bit bolder and the bottom text a bit smaller for nice visual. Photo is nice.', '2003-12-29 05:33:02.000000', NULL, 1),
(525035, 52138, 10275, '<td valign="top">I like the way the swimmer comes towards you. The yellow lines kind of help that feeling. The bottom of the photo is good, but the top is a bit grainy. You may have oversharpen it.</td>', 'I like the way the swimmer comes towards you. The yellow lines kind of help that feeling. The bottom of the photo is good, but the top is a bit grainy. You may have oversharpen it.', '2003-12-29 05:34:16.000000', NULL, 1),
(525036, 52450, 10275, '<td valign="top">Good, clean, simple image and text. Very nice simple composition.</td>', 'Good, clean, simple image and text. Very nice simple composition.', '2003-12-29 05:34:55.000000', NULL, 1),
(525037, 52176, 10275, '<td valign="top">Nice closeup. I am not big fan of flies on catus these days, but your shot has nice flow to it with the background lines seemingly streaming out of the cactus. The smaller text is kind of blurry, but still legible.</td>', 'Nice closeup. I am not big fan of flies on catus these days, but your shot has nice flow to it with the background lines seemingly streaming out of the cactus. The smaller text is kind of blurry, but still legible.', '2003-12-29 05:36:22.000000', NULL, 1),
(525038, 52431, 10275, '<td valign="top">Gorgeous photo and reflection. Love the colours and the composition is very good. I do not like the text in all caps, as it is very hard to read. Sometimes it is a good technique to darken the background behind the text a bit with a faded layer to make the text stand out from the busy background. This actually looks like a pro poster and I like it over all.</td>', 'Gorgeous photo and reflection. Love the colours and the composition is very good. I do not like the text in all caps, as it is very hard to read. Sometimes it is a good technique to darken the background behind the text a bit with a faded layer to make the text stand out from the busy background. This actually looks like a pro poster and I like it over all.', '2003-12-29 05:38:57.000000', NULL, 1),
(525040, 52444, 12802, '<td valign="top">Brilliant shot here on so many levels.<br/> <br/>Looking at the picture first, the image of the girl makes us think how lucky we are.  The dirt around her legs, feet etc and how she''s hiding looking vulnerable.<br/> <br/>Then, looking at the title it adds so much, reinforces what I was thinking.<br/> <br/>Only little niggles about this picture, the words in brackets might have looked better in the middle of the text?  And, I can see a faint box around the text that you have entered.  <br/> <br/>Great shot, 9/10</td>', 'Brilliant shot here on so many levels. Looking at the picture first, the image of the girl makes us think how lucky we are.  The dirt around her legs, feet etc and how she''s hiding looking vulnerable. Then, looking at the title it adds so much, reinforces what I was thinking. Only little niggles about this picture, the words in brackets might have looked better in the middle of the text?  And, I can see a faint box around the text that you have entered.   Great shot, 9/10', '2003-12-29 05:40:14.000000', NULL, 1),
(525041, 52466, 10275, '<td valign="top">Good idea and concept, horrendous text (sorry). Glowing neon green text is a bit too much for me, especially with script font in all caps (practically all No No''s of a good design).</td>', 'Good idea and concept, horrendous text (sorry). Glowing neon green text is a bit too much for me, especially with script font in all caps (practically all No No''s of a good design).', '2003-12-29 05:40:58.000000', NULL, 1),
(525042, 52549, 10275, '<td valign="top">Very inspirational. Although I would have chosen a bit livelier colour tone for this great man - something warmer looking.</td>', 'Very inspirational. Although I would have chosen a bit livelier colour tone for this great man - something warmer looking.', '2003-12-29 05:41:59.000000', NULL, 1),
(525043, 52455, 10275, '<td valign="top">This would have been great in the propaganda challenge as well. Well framed, but I would never put text smack in the middle of a poster. The photo should portray the message, the text is just supporting it and would have been fine along the bottom.</td>', 'This would have been great in the propaganda challenge as well. Well framed, but I would never put text smack in the middle of a poster. The photo should portray the message, the text is just supporting it and would have been fine along the bottom.', '2003-12-29 05:43:20.000000', NULL, 1),
(525044, 52271, 10275, '<td valign="top">Good concept. But it is a bit messy (probably intentionally). It''s kind of hard to find a focus point.</td>', 'Good concept. But it is a bit messy (probably intentionally). It''s kind of hard to find a focus point.', '2003-12-29 05:44:11.000000', NULL, 1),
(525045, 52546, 10275, '<td valign="top">Looks like guys are having fun. Like the way the cupboards frame the people. I am missing colour in this image. It''s lively shot, so some nice colour would have added a sparkle. Like the simple text.</td>', 'Looks like guys are having fun. Like the way the cupboards frame the people. I am missing colour in this image. It''s lively shot, so some nice colour would have added a sparkle. Like the simple text.', '2003-12-29 05:45:16.000000', NULL, 1),
(525046, 52531, 10275, '<td valign="top">Oh, very good idea. Colours are just great. The border doesn''t really go very well with your image. You have lots of colours happening, so simple border would have not competed for attention. Also, the text in yellow is a bit clownish. The main title should be bigger and different type face. If you''ve made simpler text and border, it would have been looking like a pro poster.</td>', 'Oh, very good idea. Colours are just great. The border doesn''t really go very well with your image. You have lots of colours happening, so simple border would have not competed for attention. Also, the text in yellow is a bit clownish. The main title should be bigger and different type face. If you''ve made simpler text and border, it would have been looking like a pro poster.', '2003-12-29 05:47:32.000000', NULL, 1),
(525047, 52396, 10275, '<td valign="top">Beautiful and elegant for sure. Great colours. Amazing clarity. The thin font works really nice with this image and I really appreciate that you didn''t gunk it up with a huge thick border. Very well done.</td>', 'Beautiful and elegant for sure. Great colours. Amazing clarity. The thin font works really nice with this image and I really appreciate that you didn''t gunk it up with a huge thick border. Very well done.', '2003-12-29 05:48:33.000000', NULL, 1),
(525048, 52519, 10275, '<td valign="top">Great motion feeling in this shot. Love the star effect on the lamps and how clean it is for an envening shot. Nice trails. The type face is nice for this particular poster, but the colour of the text clashes with all the red in the image. White or grey would have stand up better. Well done otherwise.</td>', 'Great motion feeling in this shot. Love the star effect on the lamps and how clean it is for an envening shot. Nice trails. The type face is nice for this particular poster, but the colour of the text clashes with all the red in the image. White or grey would have stand up better. Well done otherwise.', '2003-12-29 05:50:10.000000', NULL, 1),
(525049, 52268, 10275, '<td valign="top">Very interesting idea. The photo is a bit on the soft side (probably intentionally). The text (the smaller one) is a bit blurry. And since you centred the title, why not centre the text as well.</td>', 'Very interesting idea. The photo is a bit on the soft side (probably intentionally). The text (the smaller one) is a bit blurry. And since you centred the title, why not centre the text as well.', '2003-12-29 05:51:34.000000', NULL, 1),
(525050, 52475, 10275, '<td valign="top">Great poster. Love the photo. Not so sure about the colour of your title though. It somehow doesn''t match the red tone of your photo, it''s a bit off. Also something to consider, the text in all caps is not as simple to read as regular text would be.</td>', 'Great poster. Love the photo. Not so sure about the colour of your title though. It somehow doesn''t match the red tone of your photo, it''s a bit off. Also something to consider, the text in all caps is not as simple to read as regular text would be.', '2003-12-29 05:53:11.000000', NULL, 1),
(525052, 52285, 10275, '<td valign="top">This is so funny. Poor kitten, must be prickly. You''ve probably used flash, and due to that lost some detail in the lighter areas of the image (mainly the decorations). The text in black is ok, but the type face itself is a bit wild and could be better on the bottom of the image.</td>', 'This is so funny. Poor kitten, must be prickly. You''ve probably used flash, and due to that lost some detail in the lighter areas of the image (mainly the decorations). The text in black is ok, but the type face itself is a bit wild and could be better on the bottom of the image.', '2003-12-29 05:54:58.000000', NULL, 1),
(525053, 52527, 10275, '<td valign="top">Very soft and peaceful.</td>', 'Very soft and peaceful.', '2003-12-29 05:55:19.000000', NULL, 1),
(525054, 51876, 10275, '<td valign="top">Great catch of a shot. Like the phraze, fits well with the image. The photo has a bit of pink cast.</td>', 'Great catch of a shot. Like the phraze, fits well with the image. The photo has a bit of pink cast.', '2003-12-29 05:56:30.000000', NULL, 1),
(525056, 52405, 10275, '<td valign="top">Cute rainbow shot. It''s a bit out of focus in the front portion of the perspective, but the back is nice. The text should have been reversed white on black, instead of using block of space over your black mat. The font is also bit fancy.</td>', 'Cute rainbow shot. It''s a bit out of focus in the front portion of the perspective, but the back is nice. The text should have been reversed white on black, instead of using block of space over your black mat. The font is also bit fancy.', '2003-12-29 06:03:37.000000', NULL, 1),
(525057, 51971, 10275, '<td valign="top">Interesting viewpoint. Colours are a bit on the darker side with the top disappearing into the whiteness. But the photo itself doesn''t really make sense with your title (IMHO).</td>', 'Interesting viewpoint. Colours are a bit on the darker side with the top disappearing into the whiteness. But the photo itself doesn''t really make sense with your title (IMHO).', '2003-12-29 06:05:08.000000', NULL, 1),
(525058, 52310, 10275, '<td valign="top">Great concept and idea. Like the silver lining of the cloud and the sillueted tress. The text could have been stronger and more space around it.</td>', 'Great concept and idea. Like the silver lining of the cloud and the sillueted tress. The text could have been stronger and more space around it.', '2003-12-29 06:06:14.000000', NULL, 1),
(525059, 52334, 10275, '<td valign="top">The message of this poster is really beautiful. But here are my suggestions: when you edit background out of an image, make sure you adjust the remaining portions to the new background. The head of the man needs a contrast adjustment to make it appear more natural. Also the baby (IMO the main subject of this shot) should be more in focus. I understand you tried hard to make it appear as a pro poster, but IMO too many borders are simply too many - simplify.</td>', 'The message of this poster is really beautiful. But here are my suggestions: when you edit background out of an image, make sure you adjust the remaining portions to the new background. The head of the man needs a contrast adjustment to make it appear more natural. Also the baby (IMO the main subject of this shot) should be more in focus. I understand you tried hard to make it appear as a pro poster, but IMO too many borders are simply too many - simplify.', '2003-12-29 06:10:02.000000', NULL, 1),
(525060, 52327, 12802, '<td valign="top">It''s a good idea, maybe turning all the M''s up the same way.<br/> <br/>You could also have cloned out the two reflections in the green one.</td>', 'It''s a good idea, maybe turning all the M''s up the same way. You could also have cloned out the two reflections in the green one.', '2003-12-29 06:10:10.000000', NULL, 1),
(525061, 52002, 10275, '<td valign="top">Oh, ooo, I am in trouble. My desk is pretty clean. I must be a raving lunatic... :-))<br/> <br/>Love the sepia tone of this image. I think it simplifies it, otherwise this would look snapshottish. But it is good shot for the point you are trying to make. I also like the way you white out bottom portions of the image to make room for the text. Well done.</td>', 'Oh, ooo, I am in trouble. My desk is pretty clean. I must be a raving lunatic... :-)) Love the sepia tone of this image. I think it simplifies it, otherwise this would look snapshottish. But it is good shot for the point you are trying to make. I also like the way you white out bottom portions of the image to make room for the text. Well done.', '2003-12-29 06:11:55.000000', NULL, 1),
(525062, 52375, 10275, '<td valign="top">This would certainly be great for a sports motivational poster. Great action shot. Love how messy they are. I am not too too keen on the yeallow text with blue border. It loooks like a poster that a college student would hang in their dorm :-))</td>', 'This would certainly be great for a sports motivational poster. Great action shot. Love how messy they are. I am not too too keen on the yeallow text with blue border. It loooks like a poster that a college student would hang in their dorm :-))', '2003-12-29 06:13:40.000000', NULL, 1),
(525063, 52281, 10275, '<td valign="top">The manipulation here borders on too much. Especially the white glow around the quitar. It''s almost too simple. You definitely need the text in this image.</td>', 'The manipulation here borders on too much. Especially the white glow around the quitar. It''s almost too simple. You definitely need the text in this image.', '2003-12-29 06:14:43.000000', NULL, 1),
(525064, 52022, 10275, '<td valign="top">Neat effect of ghosting. I don''t get the "go bears" part, but it''s simple enough to enjoy.</td>', 'Neat effect of ghosting. I don''t get the "go bears" part, but it''s simple enough to enjoy.', '2003-12-29 06:15:26.000000', NULL, 1),
(525065, 52230, 10275, '<td valign="top">You are mixing too many different text styles for this to bee effective. The text on the top of the image is too much. It''s heavy and half reversed. I am not sure about this motivationg me into anything else but running away from it.</td>', 'You are mixing too many different text styles for this to bee effective. The text on the top of the image is too much. It''s heavy and half reversed. I am not sure about this motivationg me into anything else but running away from it.', '2003-12-29 06:17:42.000000', NULL, 1),
(525066, 52275, 10275, '<td valign="top">Interesting viewpoint. Like that it is b&amp;w. The mat is well done, but the red text took it over board. If your text was simply white and a bit less heavy, I would have scored it much higher.</td>', 'Interesting viewpoint. Like that it is b&w. The mat is well done, but the red text took it over board. If your text was simply white and a bit less heavy, I would have scored it much higher.', '2003-12-29 06:19:06.000000', NULL, 1),
(525067, 52468, 10275, '<td valign="top">Nice text, not so nice image. I can hardly tell what it is. The glare makes it look like a face of an alien hurtling towards me :-))) Don''t despair, I am probably one of the goofheads who doesn''t get it.</td>', 'Nice text, not so nice image. I can hardly tell what it is. The glare makes it look like a face of an alien hurtling towards me :-))) Don''t despair, I am probably one of the goofheads who doesn''t get it.', '2003-12-29 06:20:31.000000', NULL, 1),
(525069, 52510, 10275, '<td valign="top">I have absolutely no idea what this has to do with motivation. It looks like a snapshot of a fast moving car on very greay day. Sorry.</td>', 'I have absolutely no idea what this has to do with motivation. It looks like a snapshot of a fast moving car on very greay day. Sorry.', '2003-12-29 06:21:13.000000', NULL, 1),
(525071, 52501, 10275, '<td valign="top">What exactly are you promoting here? I am not sure how I should be motivated by this? To do what? Sorry for playing a dumbhead, but I don''t think this would be hanging in very many offices.</td>', 'What exactly are you promoting here? I am not sure how I should be motivated by this? To do what? Sorry for playing a dumbhead, but I don''t think this would be hanging in very many offices.', '2003-12-29 06:22:52.000000', NULL, 1),
(525072, 52301, 10275, '<td valign="top">Photo is a bit too cluttered. Also I do not understand what a lottery ticket has to do with studying. Being smarter doesn''t make you win a lottery any faster.</td>', 'Photo is a bit too cluttered. Also I do not understand what a lottery ticket has to do with studying. Being smarter doesn''t make you win a lottery any faster.', '2003-12-29 06:23:49.000000', NULL, 1),
(525074, 52128, 6771, '<td valign="top">Very nice catch.  And love the qoute.  Very true in my favorite sport.  The individuals make th whole.  Only 2 months till State Finals here in CO!!</td>', 'Very nice catch.  And love the qoute.  Very true in my favorite sport.  The individuals make th whole.  Only 2 months till State Finals here in CO!!', '2003-12-29 06:24:43.000000', NULL, 1),
(525076, 52540, 10275, '<td valign="top">Funny shot. The border is just plain bad. You need a bit of colour adjustments as well and sharpening. The text is overdone as well. Simplify and you will see how much nicer your images will be.</td>', 'Funny shot. The border is just plain bad. You need a bit of colour adjustments as well and sharpening. The text is overdone as well. Simplify and you will see how much nicer your images will be.', '2003-12-29 06:25:10.000000', NULL, 1),
(525078, 52499, 10275, '<td valign="top">Cute photo of the girls, but it has some bad yellow cast. If you intended a tone in you image, more warmer tone would have been more pleasing with this subject. This cast makes them look jaundiced. The word Dreams is OK, but the smaller text is illegible. If you didn''t use all caps, it would have been more clear.</td>', 'Cute photo of the girls, but it has some bad yellow cast. If you intended a tone in you image, more warmer tone would have been more pleasing with this subject. This cast makes them look jaundiced. The word Dreams is OK, but the smaller text is illegible. If you didn''t use all caps, it would have been more clear.', '2003-12-29 06:27:02.000000', NULL, 1),
(525081, 52332, 10275, '<td valign="top">Interesting. I understand your idea, but if you''ve actually shown some real stars or a real moon, the message would have been better. Also the choice of colour of the text is not as pleasing as if it were more finetuned with the imaga itself.</td>', 'Interesting. I understand your idea, but if you''ve actually shown some real stars or a real moon, the message would have been better. Also the choice of colour of the text is not as pleasing as if it were more finetuned with the imaga itself.', '2003-12-29 06:28:47.000000', NULL, 1),
(525082, 52544, 10275, '<td valign="top">Good luck, I hope you do well.</td>', 'Good luck, I hope you do well.', '2003-12-29 06:29:22.000000', NULL, 1),
(525085, 52238, 14401, '<td valign="top">Simply Gorgeous!</td>', 'Simply Gorgeous!', '2003-12-29 06:44:12.000000', NULL, 1),
(525086, 52472, 14401, '<td valign="top">Good idea.  The borders bother me, though, as does the top of the fence (not quite horizontal)</td>', 'Good idea.  The borders bother me, though, as does the top of the fence (not quite horizontal)', '2003-12-29 06:47:15.000000', NULL, 1),
(525088, 52310, 14401, '<td valign="top">Interesting shot.  Nice silver lining on the cloud!</td>', 'Interesting shot.  Nice silver lining on the cloud!', '2003-12-29 06:51:52.000000', NULL, 1),
(525090, 52539, 14401, '<td valign="top">Lovely!  I like the sentiment and the shot that goes with it!</td>', 'Lovely!  I like the sentiment and the shot that goes with it!', '2003-12-29 06:54:02.000000', NULL, 1),
(525091, 52181, 14401, '<td valign="top">Great sharp picture of the bird!</td>', 'Great sharp picture of the bird!', '2003-12-29 06:54:44.000000', NULL, 1),
(525092, 52537, 14401, '<td valign="top">Very cute!  I''m sure your local dojo would appreciate a copy of this!</td>', 'Very cute!  I''m sure your local dojo would appreciate a copy of this!', '2003-12-29 06:55:42.000000', NULL, 1),
(525094, 52364, 14401, '<td valign="top">Good job!</td>', 'Good job!', '2003-12-29 06:56:41.000000', NULL, 1),
(525095, 52431, 14401, '<td valign="top">This is really gorgeous.  The one thing I''d change, however, would be to make the smaller text upper/lower case.  I come from a background of typography, and it is proven that upper/lower mix is easier to read than all caps.</td>', 'This is really gorgeous.  The one thing I''d change, however, would be to make the smaller text upper/lower case.  I come from a background of typography, and it is proven that upper/lower mix is easier to read than all caps.', '2003-12-29 06:59:11.000000', NULL, 1),
(525096, 51971, 14401, '<td valign="top">This is a wild shot.  Not sure I quite follow the text, but I''m guessing that we come from different cultures.</td>', 'This is a wild shot.  Not sure I quite follow the text, but I''m guessing that we come from different cultures.', '2003-12-29 07:00:28.000000', NULL, 1),
(525097, 52467, 14401, '<td valign="top">One of my favorites in this challenge!  Great typography!</td>', 'One of my favorites in this challenge!  Great typography!', '2003-12-29 07:01:29.000000', NULL, 1),
(525099, 52414, 14401, '<td valign="top">Interesting idea.  I''m afraid the colors don''t work too well for me.</td>', 'Interesting idea.  I''m afraid the colors don''t work too well for me.', '2003-12-29 07:02:58.000000', NULL, 1),
(525100, 52526, 14401, '<td valign="top">Another favorite!  This is one of the best I''ve seen in the challenge!</td>', 'Another favorite!  This is one of the best I''ve seen in the challenge!', '2003-12-29 07:04:10.000000', NULL, 1),
(525101, 51919, 14401, '<td valign="top">Interesting take - I like the image.  Grammatically, though, an error.  Should be "than" now rather than "then".</td>', 'Interesting take - I like the image.  Grammatically, though, an error.  Should be "than" now rather than "then".', '2003-12-29 07:05:42.000000', NULL, 1),
(525102, 51901, 14401, '<td valign="top">Nice, simple.</td>', 'Nice, simple.', '2003-12-29 07:06:23.000000', NULL, 1),
(525103, 52540, 14401, '<td valign="top">Cute.  Very interesting take on the challenge - a little soft focus.  Text is a little over-emphasized by the effects used which weakens it for me.</td>', 'Cute.  Very interesting take on the challenge - a little soft focus.  Text is a little over-emphasized by the effects used which weakens it for me.', '2003-12-29 07:08:19.000000', NULL, 1),
(525105, 52490, 4008, '<td valign="top">Great image, great poster.</td>', 'Great image, great poster.', '2003-12-29 07:10:12.000000', NULL, 1),
(525106, 52490, 14401, '<td valign="top">Nice. I think the text is a little too intense a blue, but not bad.</td>', 'Nice. I think the text is a little too intense a blue, but not bad.', '2003-12-29 07:10:23.000000', NULL, 1),
(525107, 52541, 14401, '<td valign="top">Gorgeous!  The typography is excellent as is the image!  "10"</td>', 'Gorgeous!  The typography is excellent as is the image!  "10"', '2003-12-29 07:11:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(525108, 52384, 14401, '<td valign="top">Beautiful little guy!</td>', 'Beautiful little guy!', '2003-12-29 07:12:28.000000', NULL, 1),
(525109, 51919, 2780, '<td valign="top">I''m sure I won''t be the only person to point out the typo (then/than) but I do like this picture a lot. 8</td>', 'I''m sure I won''t be the only person to point out the typo (then/than) but I do like this picture a lot. 8', '2003-12-29 07:12:28.000000', NULL, 1),
(525110, 52557, 14401, '<td valign="top">Perfect shot, perfectly wonderful sentiment.  Good typography.</td>', 'Perfect shot, perfectly wonderful sentiment.  Good typography.', '2003-12-29 07:13:37.000000', NULL, 1),
(525111, 51884, 9913, '<td valign="top">Alcohol sure is a solution for a suffering alcoholic, But from my experience AA is a much better and loger lasting solution;)<br/> <br/>The idea of the shot is pretty cool But I think the background could be better composed so I´ll have to give you a 5</td>', 'Alcohol sure is a solution for a suffering alcoholic, But from my experience AA is a much better and loger lasting solution;) The idea of the shot is pretty cool But I think the background could be better composed so I´ll have to give you a 5', '2003-12-29 07:13:55.000000', NULL, 1),
(525112, 52444, 9913, '<td valign="top">very emotional and strong photo</td>', 'very emotional and strong photo', '2003-12-29 07:14:22.000000', NULL, 1),
(525113, 52530, 2780, '<td valign="top">I like the photo a lot, but I think the design in the border is a bit too heavy. 8</td>', 'I like the photo a lot, but I think the design in the border is a bit too heavy. 8', '2003-12-29 07:14:33.000000', NULL, 1),
(525114, 52328, 14401, '<td valign="top">Great poster!  Should be required in every government office, LOL!</td>', 'Great poster!  Should be required in every government office, LOL!', '2003-12-29 07:14:52.000000', NULL, 1),
(525115, 52215, 14401, '<td valign="top">Cute squirrel!  Looks like you created text as art, and there are artifacts which are distracting for me - but I know those could be cleaned up.</td>', 'Cute squirrel!  Looks like you created text as art, and there are artifacts which are distracting for me - but I know those could be cleaned up.', '2003-12-29 07:16:26.000000', NULL, 1),
(525116, 52181, 2780, '<td valign="top">I think you should have made the vertical lines even, rather than the horizontal, as this seems too far tilted to the right to me.  Also, a white keyline seperating the photo from the border would have helped the shot. 6</td>', 'I think you should have made the vertical lines even, rather than the horizontal, as this seems too far tilted to the right to me.  Also, a white keyline seperating the photo from the border would have helped the shot. 6', '2003-12-29 07:17:17.000000', NULL, 1),
(525118, 52561, 14401, '<td valign="top">This is an interesting image, but seems to me to be at variance with the text.  Cheap pearls and bourbon don''t really project an image of success in my mind.</td>', 'This is an interesting image, but seems to me to be at variance with the text.  Cheap pearls and bourbon don''t really project an image of success in my mind.', '2003-12-29 07:18:54.000000', NULL, 1),
(525119, 52521, 4008, '<td valign="top">Great color and text. You could crop away one third of the lower part of the image. Would make it even stronger in my opinion.</td>', 'Great color and text. You could crop away one third of the lower part of the image. Would make it even stronger in my opinion.', '2003-12-29 07:19:53.000000', NULL, 1),
(525121, 52136, 14401, '<td valign="top">Lovely image.</td>', 'Lovely image.', '2003-12-29 07:21:18.000000', NULL, 1),
(525122, 52460, 14401, '<td valign="top">I love it - an unexpected image to go with a common quote.  Great job!</td>', 'I love it - an unexpected image to go with a common quote.  Great job!', '2003-12-29 07:23:06.000000', NULL, 1),
(525124, 52534, 14401, '<td valign="top">What pretty blue eyes!  A little soft of focus - but very nice.</td>', 'What pretty blue eyes!  A little soft of focus - but very nice.', '2003-12-29 07:25:28.000000', NULL, 1),
(525129, 52138, 14401, '<td valign="top">Great photo, great quote!  Just need to get it on the poster now!</td>', 'Great photo, great quote!  Just need to get it on the poster now!', '2003-12-29 07:27:57.000000', NULL, 1),
