(526082, 51848, 14766, '<td valign="top">nice idea - dominos usually used for falling down themes - so taking the standing up straight approach makes the point well. I like the way the dots are invisible everywhere else to add to the focus on the action pieces.</td>', 'nice idea - dominos usually used for falling down themes - so taking the standing up straight approach makes the point well. I like the way the dots are invisible everywhere else to add to the focus on the action pieces.', '2003-12-30 06:09:07.000000', NULL, 1),
(526098, 51901, 669, '<td valign="top">Nice shot, but I think I''d prefer the shot slightly larger.  Admittedly it''s somewhat more difficult with a 3:2 shot.</td>', 'Nice shot, but I think I''d prefer the shot slightly larger.  Admittedly it''s somewhat more difficult with a 3:2 shot.', '2003-12-30 07:43:15.000000', NULL, 1),
(526100, 52477, 669, '<td valign="top">Nicely done.  Text font/etc looks spot on.  Might have chosen a slightly lighter colour?  The sign is a little out of the pic, but I don''t think that''s a bad thing.  Nice amount of texture and detail.</td>', 'Nicely done.  Text font/etc looks spot on.  Might have chosen a slightly lighter colour?  The sign is a little out of the pic, but I don''t think that''s a bad thing.  Nice amount of texture and detail.', '2003-12-30 07:44:34.000000', NULL, 1),
(526101, 52479, 669, '<td valign="top">Very nice production, but the shot looks a little cluttered.</td>', 'Very nice production, but the shot looks a little cluttered.', '2003-12-30 07:45:25.000000', NULL, 1),
(526103, 52431, 669, '<td valign="top">Fantastic colour of the water.  I hope that''s real!  I''m not at all keen on the text however, sorry.  Especially on the words "Reflection" and "words" at the end it''s very difficult to read.  I would have been tempted to use a solid border.  Good effort.</td>', 'Fantastic colour of the water.  I hope that''s real!  I''m not at all keen on the text however, sorry.  Especially on the words "Reflection" and "words" at the end it''s very difficult to read.  I would have been tempted to use a solid border.  Good effort.', '2003-12-30 07:46:51.000000', NULL, 1),
(526104, 52414, 669, '<td valign="top">Interesting use of subjects.  It''s nice and vibrant!  I really would have put the text straight.  Also the text seems very smoothly anti-aliased with the background, which looks a little harsh.  Good effort.</td>', 'Interesting use of subjects.  It''s nice and vibrant!  I really would have put the text straight.  Also the text seems very smoothly anti-aliased with the background, which looks a little harsh.  Good effort.', '2003-12-30 07:48:12.000000', NULL, 1),
(526105, 52559, 669, '<td valign="top">I realise the shot is a silouette, but I can''t quite make out what I''m looking at.  If poss I''d prefer a little more detail in the ground at the bottom (maybe achieved using levels?).  Otherwise, very nicely done.</td>', 'I realise the shot is a silouette, but I can''t quite make out what I''m looking at.  If poss I''d prefer a little more detail in the ground at the bottom (maybe achieved using levels?).  Otherwise, very nicely done.', '2003-12-30 07:49:43.000000', NULL, 1),
(526106, 52444, 669, '<td valign="top">Very powerful message, and a great shot.  Think the border is a little over done, otherwise pretty spot on.  Top 10 or higher, maybe?</td>', 'Very powerful message, and a great shot.  Think the border is a little over done, otherwise pretty spot on.  Top 10 or higher, maybe?', '2003-12-30 07:51:00.000000', NULL, 1),
