(526418, 52459, 12733, '<td valign="top">Beautiful reflections of the dawn and a nice rendition of the moving water.</td>', 'Beautiful reflections of the dawn and a nice rendition of the moving water.', '2003-12-30 15:12:50.000000', NULL, 1),
(526422, 52542, 12332, '<td valign="top">Wow!  Super!  Better than most posters actually for sale in the stores!  (10)</td>', 'Wow!  Super!  Better than most posters actually for sale in the stores!  (10)', '2003-12-30 15:14:22.000000', NULL, 1),
