(528202, 52238, 14601, '<td valign="top">Superb entry for the challenge. Crisp, great color,  and just the right shutter speed to capture the water''s movement. The choice of font works very well with this image, as well. Great job all around.</td>', 'Superb entry for the challenge. Crisp, great color,  and just the right shutter speed to capture the water''s movement. The choice of font works very well with this image, as well. Great job all around.', '2004-01-01 09:42:35.000000', NULL, 1),
(528204, 52364, 8860, '<td valign="top">Great photo - very crisp and well composed.<br/>Typography is too low in the frame and tight to the edge.</td>', 'Great photo - very crisp and well composed.Typography is too low in the frame and tight to the edge.', '2004-01-01 09:42:58.000000', NULL, 1),
(528205, 52544, 14601, '<td valign="top">Wow. This image is incredible enough on its own - but encased in that nice thick black border the image really pops. Nice font selection, as well.</td>', 'Wow. This image is incredible enough on its own - but encased in that nice thick black border the image really pops. Nice font selection, as well.', '2004-01-01 09:46:36.000000', NULL, 1),
(528208, 52196, 14601, '<td valign="top">Great capture, super focus, dof, etc., nice cropping, borders, font, etc. A couple of hot spots on the ball are slightly distracting, but other than that, it''s a perfect entry for this challenge.</td>', 'Great capture, super focus, dof, etc., nice cropping, borders, font, etc. A couple of hot spots on the ball are slightly distracting, but other than that, it''s a perfect entry for this challenge.', '2004-01-01 09:49:53.000000', NULL, 1),
(528213, 52542, 14601, '<td valign="top">Imaginative selection of a round mat - I like it, and it fits perfectly with the image, which is, itself, a great capture. Nice choice of border color, font type/size, etc.  One minor criticism: You should have given William Blake credit for the quotation.</td>', 'Imaginative selection of a round mat - I like it, and it fits perfectly with the image, which is, itself, a great capture. Nice choice of border color, font type/size, etc.  One minor criticism: You should have given William Blake credit for the quotation.', '2004-01-01 09:54:33.000000', NULL, 1),
(528224, 52557, 14601, '<td valign="top">Love the contrast in color - more subdued in sky and statue, pops the flag. Great capture, nicely framed, good selection of quote ( Pericles? ), nice font choice.</td>', 'Love the contrast in color - more subdued in sky and statue, pops the flag. Great capture, nicely framed, good selection of quote ( Pericles? ), nice font choice.', '2004-01-01 10:02:18.000000', NULL, 1),
(528229, 52490, 14601, '<td valign="top">Super entry for this challenge. Nice job with cropping, layout, borders, font, etc. The "typical" view would be more of a flying "V" shape, but I kind of like this better - shows that not all teams are "V" shaped.</td>', 'Super entry for this challenge. Nice job with cropping, layout, borders, font, etc. The "typical" view would be more of a flying "V" shape, but I kind of like this better - shows that not all teams are "V" shaped.', '2004-01-01 10:06:00.000000', NULL, 1),
(528235, 52541, 14601, '<td valign="top">First, let me say that I love everything about this entry except for not crediting Eleonora Duse with the original quote. It originally said "If a blade of grass has the power...".</td>', 'First, let me say that I love everything about this entry except for not crediting Eleonora Duse with the original quote. It originally said "If a blade of grass has the power...".', '2004-01-01 10:12:11.000000', NULL, 1),
(528238, 52539, 14601, '<td valign="top">Beautiful capture, great color, layout, borders, etc. Nice selection of font placement, size, etc. Great quote ( You should have given credit for that to Oliver Wendell Holmes ).</td>', 'Beautiful capture, great color, layout, borders, etc. Nice selection of font placement, size, etc. Great quote ( You should have given credit for that to Oliver Wendell Holmes ).', '2004-01-01 10:15:09.000000', NULL, 1),
