(529842, 52364, 210, '<td valign="top">The framing feels a bit off... otherwise, beautiful and meaningful shot.</td>', 'The framing feels a bit off... otherwise, beautiful and meaningful shot.', '2004-01-02 17:22:30.000000', NULL, 1),
