(530014, 52535, 9932, '<td valign="top">A little more contrast from the rocks and the back two surfers would have helped alot I think. Plus a different choice in font for the title. Nice work.</td>', 'A little more contrast from the rocks and the back two surfers would have helped alot I think. Plus a different choice in font for the title. Nice work.', '2004-01-02 19:58:29.000000', NULL, 1),
(530015, 52542, 9932, '<td valign="top">Excellent, very nice work. I think the yellow circle and yellow text are a bit to much but still well done.</td>', 'Excellent, very nice work. I think the yellow circle and yellow text are a bit to much but still well done.', '2004-01-02 19:59:37.000000', NULL, 1),
(530017, 52550, 9932, '<td valign="top">Very nice shot. But this was motivational poster? Where is the title? Motivation?</td>', 'Very nice shot. But this was motivational poster? Where is the title? Motivation?', '2004-01-02 20:00:34.000000', NULL, 1),
