(530312, 52414, 15540, '<td valign="top">Too simple. a spider that is walking on a tight rope represents you can layout the photo a little more realistically.</td>', 'Too simple. a spider that is walking on a tight rope represents you can layout the photo a little more realistically.', '2004-01-03 03:22:22.000000', NULL, 1),
(530313, 52467, 15540, '<td valign="top">Very pleasant, lets me understand individuality.</td>', 'Very pleasant, lets me understand individuality.', '2004-01-03 03:23:20.000000', NULL, 1),
(530314, 52538, 15540, '<td valign="top">Great for business environment.</td>', 'Great for business environment.', '2004-01-03 03:23:36.000000', NULL, 1),
(530315, 52501, 15540, '<td valign="top">Good photo but not for a motivational poster. Especially about sexual promimsuity. Use for something else. Maybe use it for something about greenpeace. Saving the forests. Something like that.</td>', 'Good photo but not for a motivational poster. Especially about sexual promimsuity. Use for something else. Maybe use it for something about greenpeace. Saving the forests. Something like that.', '2004-01-03 03:24:57.000000', NULL, 1),
