(530323, 52405, 15540, '<td valign="top">Foreground is too blurry. Try and balance the focus for the whole picure.</td>', 'Foreground is too blurry. Try and balance the focus for the whole picure.', '2004-01-03 03:33:43.000000', NULL, 1),
