(530328, 52364, 15540, '<td valign="top">Great in showing how to get somewhere. This is motivational (although mountains are becoming cliche). This worked really well. If the person was a little more identifiable. The line leads to him, but you have to really recognize that he''s there.</td>', 'Great in showing how to get somewhere. This is motivational (although mountains are becoming cliche). This worked really well. If the person was a little more identifiable. The line leads to him, but you have to really recognize that he''s there.', '2004-01-03 03:39:48.000000', NULL, 1),
(530329, 52163, 15540, '<td valign="top">For shear creativity.</td>', 'For shear creativity.', '2004-01-03 03:40:31.000000', NULL, 1),
(530330, 51995, 15540, '<td valign="top">If the arrow was more a part of the floor, not overlapping his hand, better. His dar face needs a little more lightening.</td>', 'If the arrow was more a part of the floor, not overlapping his hand, better. His dar face needs a little more lightening.', '2004-01-03 03:41:57.000000', NULL, 1),
