(531405, 52546, 9932, '<td valign="top">Doesn''t motivate me? <br/>Looks like a group of men that are all thumbs and wishing it was a football instead? <br/>A better title may have been: "Manual we don''t need any stinkin manual" :)<br/>I like the idea but not the final work.<br/> I hope you do not take this the wrong way. I have to find humor in somethngs.</td>', 'Doesn''t motivate me? Looks like a group of men that are all thumbs and wishing it was a football instead? A better title may have been: "Manual we don''t need any stinkin manual" :)I like the idea but not the final work. I hope you do not take this the wrong way. I have to find humor in somethngs.', '2004-01-04 14:36:01.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(531408, 52512, 9932, '<td valign="top">Real nice. Could have dressed it up more to be a poster (just my feeling though).<br/>I would not buy this as a poster. Though this does not really affect my vote that much.</td>', 'Real nice. Could have dressed it up more to be a poster (just my feeling though).I would not buy this as a poster. Though this does not really affect my vote that much.', '2004-01-04 14:39:02.000000', NULL, 1),
(531409, 52559, 9932, '<td valign="top">Usually with a poster there is some connection with the photo and the phrase. I do not see that here.</td>', 'Usually with a poster there is some connection with the photo and the phrase. I do not see that here.', '2004-01-04 14:40:47.000000', NULL, 1),
(531410, 52519, 9932, '<td valign="top">I like the shot I like the title but I do not like nor agree with your catch phrase/sub title.</td>', 'I like the shot I like the title but I do not like nor agree with your catch phrase/sub title.', '2004-01-04 14:42:59.000000', NULL, 1),
